//refAssemblies: TCAdmin.Monitor.SDK.dll, System.Diagnostics.Process.dll, System.Net.Http.dll, System.Text.Json.dll
using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// --start-server needs an existing save. Create the map on the first start (or after the save name changed);
// the script runs as the monitor, so the new files are handed to the service user afterwards.
var root = (string)ThisService.RootDirectory;
var saveName = ThisService.Variables.ContainsKey("SaveName") ? Convert.ToString(ThisService.Variables["SaveName"]) : "";
if (string.IsNullOrWhiteSpace(saveName)) saveName = "world";
var save = Path.Combine(root, "saves", saveName + ".zip");
if (!File.Exists(save))
{
    ScriptConsole.WriteLine((object)("Creating a new map: saves/" + saveName + ".zip"));
    Directory.CreateDirectory(Path.GetDirectoryName(save));
    if (!Shell("cd '" + root + "' && ./bin/x64/factorio --create 'saves/" + saveName + ".zip'", out var output) || !File.Exists(save))
        throw new Exception("Creating the map failed: " + output);
    var credential = ServiceManagerService.GetServiceCredential(ThisService.ServiceId);
    Globals.OperatingSystem.SetDirectoryOwner(root, credential.Domain, credential.UserName, true);
}
